  const norm = s => String(s || '').normalize('NFKC').toLowerCase().replace(/[’‘]/g, "'").replace(/\s+/g, ' ').trim();

  function apply(data) {
    if (!data || !Array.isArray(data.cards)) return data;
    const seen = new Set();
    for (const c of data.cards) {
      if (c && c.term) seen.add(norm(c.term));
    }
    let added = 0;
    for (const card of CARDS) {
      const k = norm(card.term);
      if (!seen.has(k)) {
        data.cards.push(card);
        seen.add(k);
        added++;
      }
    }
    if (added > 0 || data.cards.some(c => c && String(c.id || '').startsWith('vnew10-'))) {
      const totalW10 = data.cards.filter(c => c && String(c.id || '').startsWith('vnew10-')).length;
      if (typeof data.cardCount === 'number') data.cardCount = data.cards.length;
      if (Array.isArray(data.topics) && !data.topics.some(t => t && t.id === 'vnexpress-w10-700')) {
        data.topics.unshift({
          id: 'vnexpress-w10-700',
          title: 'VnExpress 700 · Báo chí quốc tế (Đợt 10)',
          description: '2,008 cụm từ IELTS Band 8.5–9.0 cân bằng loại từ lọc từ 867 bài báo mới trên VnExpress International, kèm giải thích 4 phần.',
          accent: 'cyan'
        });
      }
      if (Array.isArray(data.sources) && !data.sources.some(s => s && s.id === 'vnexpress-w10-700')) {
        data.sources.push({
          id: 'vnexpress-w10-700',
          title: 'VnExpress 700 (Đợt 10) · 867 bài báo quốc tế mới (Band 8.5–9.0)',
          category: 'Academic vocabulary',
          originalCount: totalW10,
          supplements: 0
        });
      }
    }
    return data;
  }

  function getShard(shard) {
    const key = String(shard || '').toLowerCase();
    return EXPLANATIONS_BY_SHARD[key] || null;
  }

  function getExplanation(id) {
    const key = String(id || '').toLowerCase();
    if (key.length < 2) return null;
    const bucket = EXPLANATIONS_BY_SHARD[key.slice(0, 2)];
    return bucket ? (bucket[key] || null) : null;
  }

